    class Game2048 {
        constructor() {
            this._score = 0;
            this._board = Array.from({length: SIZE}, () => Array(SIZE).fill(0));

            document.getElementById('reset-btn').addEventListener('click', () => this.reset());

            window.addEventListener('keydown', (e) => {
                const keys = ['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'];
                if (!keys.includes(e.key)) return;
                let dir='';
                switch(e.key){ 
                    case 'ArrowUp': dir='up'; break; 
                    case 'ArrowDown': dir='down'; break; 
                    case 'ArrowLeft': dir='left'; break; 
                    case 'ArrowRight': dir='right'; break; 
                }
                if(dir) { e.preventDefault(); this.move(dir); }
            });

            this.renderBoard();
        }

        get size() { return SIZE; }

        _spawnTile() {
            const zeros = [];
            for(let r=0; r<SIZE; r++) {
                for(let c=0; c<SIZE; c++) {
                    if(this._board[r][c] === 0) zeros.push({r, c});
                }
            }
            if (zeros.length > 0) {
                const pos = zeros[Math.floor(Math.random() * zeros.length)];
                this._board[pos.r][pos.c] = Math.random() < 0.1 ? 4 : 2;
            }
        }

        // Helper: compress line towards index 0 (left/up equivalent), merge adjacent equals once per iteration, pad with zeros at end.
        _compressAndMerge(line) {
            let res = [];
            let scoreGain = 0;

            for(let i=0; i<line.length; ) {
                if(i+1 < line.length && line[i] === line[i+1]) {
                    const sumVal = line[i] * 2;
                    res.push(sumVal);
                    scoreGain += sumVal;
                    i += 2; // Skip next item as it's merged
                } else {
                    if(line[i] !== 0) res.push(line[i]);
                    i++;
                }
            }

            while(res.length < SIZE) res.push(0);

            return [res, scoreGain];
        }

        move(direction) {
            const oldBoard = JSON.parse(JSON.stringify(this._board)); // deep copy for comparison

            let totalScoreGain = 0;
            const newBoard = Array.from({length: SIZE}, () => Array(SIZE).fill(0));

            if (['left', 'right'].includes(direction)) {
                for(let r=0; r<SIZE; r++) {
                    let rowArr = this._board[r];

                    // For Right, we reverse input to simulate LeftSlide on reversed array.
                    const revRow = direction === 'right' ? rowArr.slice().reverse() : rowArr;
                    const [processedRev, gain] = this._compressAndMerge(revRow);

                    if (direction === 'right') {
                        // Reverse result back to align with original columns correctly for Right slide.
                        newBoard[r] = processedRev.slice().reverse(); 
                    } else {
                        newBoard[r] = processedRev;
                    }

                    totalScoreGain += gain;
                }

            } else if (['up', 'down'].includes(direction)) {
