                        for(let r=0; r<SIZE; r++) newBoard[r][c] = processedRev[r];
                    }

                    totalScoreGain += gain;
                }
            }

            if (JSON.stringify(newBoard) !== JSON.stringify(oldBoard)) {
                this._board = newBoard;
                this._score += totalScoreGain;

                // Only spawn tile after successful move
                this._spawnTile();
                this.updateUI();
                return true;
            }

            return false;
        }

