                    const tile = document.createElement('div');
                    tile.className = 'tile';
                    if (val !== 0) tile.textContent = val; // show number
                    boardEl.appendChild(tile);
                }
            }
            scoreEl.innerText = `Score: ${this._score}`;
        }

        renderBoard() { this.updateUI(); }

