        }

        setBoard(arr) {
            // Set grid exactly, no spawn. Update DOM immediately for grading visibility.
            if (arr.length === SIZE && arr[0].length === SIZE) {
                this._board = Array.from({length: SIZE}, (_, r) => arr[r].slice());
                this.updateUI();
            } else {
                console.error("Invalid board size");
            }
        }
    } // End Class

    const gameInstance = new Game2048();

    window.game = {
        get size() { return 4; },
        reset: () => gameInstance.reset(),
        move: (dir) => gameInstance.move(dir),
        board: () => JSON.parse(JSON.stringify(gameInstance._board)), // Return deep copy to prevent external mutation side effects.
        setBoard: (arr) => gameInstance.setBoard(arr),
        score: () => gameInstance._score,
    };

})();
</script>
